style.css:
@-moz-document domain("youtube.com") {
body {
        background-color: #1c1c1c; /* Fondo oscuro */
        color: white; /* Texto blanco */
    }

    /* Cambiar los colores de los botones */
    .ytp-play-button {
        background-color: #ff0000 !important;
    }

    /* Cambiar el color del título del video */
    #video-title {
        color: #ff6347; /* Título en color tomate */
    }

    /* Cambiar el fondo de la barra lateral */
    #guide {
        background-color: #2a2a2a;
    }

    /* Cambiar el color de los enlaces */
    a {
        color: #4CAF50; /* Enlaces verdes */
    }
}
